"""Synthetic policy corpus. These are invented demo policies, not legal guidance."""
import json
from pathlib import Path

CORPUS = [
("annual_leave.md", "Annual leave policy", "All", "internal", "Permanent employees receive 25 working days of annual leave per calendar year. Leave must be requested in the HR portal at least 10 working days before the start date. The employee's line manager approves annual leave. Employees may carry forward up to 5 unused working days, which must be used by 31 March of the following year. Unused carried days expire after that date. This policy applies to permanent employees of the fictional Meridian Telecom company."),
("travel_expenses.md", "Domestic travel and expenses", "All", "internal", "For approved domestic business travel, the meal reimbursement limit is AED 150 per person per day. The domestic hotel limit is AED 750 per night. Employees must attach itemized receipts and submit their expense claim within 7 calendar days after returning. The line manager approves the business purpose before travel. Finance reviews the receipts before reimbursement. Personal entertainment and expenses without receipts are not reimbursable under this policy."),
("security_awareness.md", "Reporting phishing and security concerns", "All", "internal", "Report suspected phishing emails to security@meridian.example within 15 minutes of discovery using the Report Phishing button in the mail application. Do not click suspicious links, open attachments, or reply to the sender. If a link was already clicked, disconnect the device from the network and contact the IT service desk immediately. Preserve the original email for the security team. This mailbox is a fictional demonstration address; the copilot does not send emails."),
("remote_work.md", "Remote work policy", "All", "internal", "Eligible employees may work remotely up to 2 days per week with prior line-manager approval. Remote days must be recorded in the team calendar before the week begins. Employees must use a company-managed device and the corporate VPN when accessing internal systems. Customer service coverage and operational duties take priority over remote scheduling. Working remotely does not change document permissions or permit copying company records to a personal device."),
("procurement.md", "Purchase request procedure", "All", "internal", "Employees submit purchase requests with a business justification and a supplier quotation. Requests up to AED 500 require line-manager approval. Requests above AED 500 and up to AED 5000 require Procurement approval. Requests above AED 5000 require both Procurement and Finance approval. Split purchases intended to avoid an approval threshold are prohibited. The requester must wait for approval before placing an order. This application only explains the policy; it cannot place orders."),
("it_passwords.md", "IT account and password standard", "IT", "internal", "IT administrators configure staff passwords to require at least 14 characters and multi-factor authentication. An account is temporarily locked after 5 consecutive failed sign-in attempts. Password resets require identity verification by the IT service desk. Temporary reset links expire after 30 minutes. Administrators must never ask employees to send their current passwords in chat or email. Shared administrator accounts are prohibited. Access changes require a separate approved access request."),
("it_devices.md", "IT device replacement procedure", "IT", "internal", "The standard replacement cycle for company laptops is 3 years. Early replacement requires an IT assessment of hardware failure or a documented accessibility need. Employees open a service-desk ticket with the asset tag, symptoms, and business impact. The IT asset team reviews the request within 2 business days. Devices must be securely wiped by IT before disposal or reassignment. Staff must not dispose of company devices themselves."),
("hr_onboarding.md", "HR onboarding checklist", "HR", "internal", "HR creates a new starter record at least 5 working days before the joining date. The onboarding coordinator verifies the signed offer and emergency contact details, then requests an IT account and equipment. The new starter attends orientation within the first 2 working days. The line manager completes the role induction checklist within 10 working days. HR keeps the signed checklist in the restricted personnel record. This procedure contains synthetic demonstration requirements."),
("hr_records.md", "HR personnel records handling", "HR", "internal", "Personnel records are restricted to authorized HR staff. The internal demonstration retention period is 7 years after an employee leaves the organization. Any request to export personnel records must be reviewed by the HR manager and the privacy officer. Records must not be attached to general support tickets or posted in shared chat channels. Corrections must preserve an audit trail showing the date, author, and reason for the change."),
("operations_incidents.md", "Network incident response", "Operations", "internal", "A priority-one network incident must be acknowledged within 15 minutes. The incident commander publishes a status update every 30 minutes until service is restored. The on-call engineer records the affected service, start time, symptoms, and immediate containment steps. The operations manager approves external customer updates. A post-incident review is completed within 3 business days after restoration. Incident priority is based on service impact, not on the seniority of the requester."),
("operations_changes.md", "Planned network change procedure", "Operations", "internal", "Routine network changes use the Wednesday maintenance window from 22:00 to 02:00 local time. Submit a change request at least 2 business days before the maintenance window. Every request includes the affected services, implementation steps, a tested rollback plan, and validation checks. The change manager approves the request before execution. Emergency changes require explicit approval from the on-call operations manager and a retrospective review on the next business day."),
("leadership_reserve.md", "Operations leadership contingency reserve", "Operations", "leadership", "The fictional Operations leadership contingency reserve is AED 250000 for the current planning cycle. The internal planning code is ORBIT. Only Operations managers and platform administrators may view this document. Use of the reserve requires written approval from the Operations director and Finance. The reserve is not an employee allowance and must not be included in general employee policy answers. This document exists to demonstrate restricted retrieval."),
("leadership_bonus.md", "Leadership discretionary bonus review", "All", "leadership", "The fictional leadership review guideline caps discretionary recognition bonuses at 12 percent of annual base pay. A committee consisting of HR leadership and Finance must approve each recommendation. A manager cannot approve their own recommendation. This guideline is restricted to leadership and administrators. It does not establish an employee entitlement, and the copilot must not promise payment or claim that a bonus has been approved."),
]

if __name__ == "__main__":
    root = Path(__file__).resolve().parents[1] / "sample_docs"
    root.mkdir(exist_ok=True)
    manifest = []
    for filename, title, department, classification, body in CORPUS:
        (root / filename).write_text(f"# {title}\n\n{body}\n", encoding="utf-8")
        manifest.append(dict(filename=filename, title=title, department=department, classification=classification))
    (root / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    print(f"Prepared {len(manifest)} synthetic documents.")
